print("********SEQUENCETYPE*******")
#A sequence type is a data type that stores multiple values in an ordered manner, where each element can be accessed using an index.
print("******LIST******")
x=["apple","banana","cherry"]
print(x)
print(type(x))
#Can store different data types
#Mutable (can change)
#Most commonly used

print("********TUPLE******")
y=("apple","banana","cherry")
print(type(y))
#Faster than list
#Immutable
#Used for fixed data

print("****range********")
z=range(9)
print(list(z))
#range is a built-in sequence type in Python used to generate a sequence of numbers.

